(() => {
 const {M,sum,clamp,m,p,a,sel,yes,refs,bars,out,line,add}=CREDIT_UI,stage='04 · IFRS 9 and expected credit loss',sources=[refs.ifrs,refs.ecl];
 add({id:'scope',name:'IFRS 9 scope and measurement routes',stage,title:'First choose the accounting route. Then calculate the allowance.',intro:'Explore where the general impairment model, simplified approach and POCI treatment apply.',chart:'Illustrative gross balance and loss allowance (£m)',inputs:[sel('type','Instrument / measurement category',[['ac','Debt at amortised cost'],['fvoci','Debt at FVOCI'],['trade','Trade receivable without significant financing'],['lease','Lease receivable · simplified policy elected'],['commit','Loan commitment within IFRS 9 impairment scope'],['poci','Purchased/originated credit-impaired asset'],['fvtpl','Asset at FVTPL'],['equity','Equity designated FVOCI']],'ac'),a('gross','Exposure / carrying amount assumption',10,200,10,100),a('loss','Illustrative loss fraction',0,40,1,3,'%')],challenge:'Why should a FVTPL asset not receive a separate general-model ECL allowance?',formula:'Identify measurement category and impairment scope before choosing ECL horizon',simple:'The same economic credit concern can enter accounting through different measurement routes. Fair-value changes, a separate allowance and POCI changes must not be mixed into one rule.',scope:'Scope map only. Debt classification also requires business-model and contractual-cash-flow (SPPI) assessment; equity FVOCI is not the debt FVOCI impairment route. Selected commitment assumed not measured at FVTPL. Lease simplified policy is explicitly elected. The percentage is illustrative, not an ECL model. FVOCI debt allowance is recognised in OCI without reducing the asset’s statement-of-financial-position fair value.',sources,compute(s){const map={ac:['General approach','12-month or lifetime ECL according to credit deterioration'],fvoci:['General approach','ECL in profit or loss with corresponding OCI presentation'],trade:['Simplified approach','Lifetime ECL without general-model SICR tracking'],lease:['Simplified policy','Lifetime ECL under the elected policy'],commit:['General approach','Provision for in-scope expected credit losses'],poci:['POCI specific route','Cumulative changes in lifetime ECL since initial recognition'],fvtpl:['No separate ECL allowance','Credit effects enter fair value through profit or loss'],equity:['No IFRS 9 ECL allowance','Equity FVOCI has different measurement requirements']},x=map[s.type],excluded=['fvtpl','equity'].includes(s.type),v=excluded||s.type==='poci'?0:s.gross*s.loss/100;return out([['Route',x[0]],['Selected amount',m(s.gross)],['Illustrative allowance',s.type==='poci'?'Use POCI lesson':m(v)]],['Selected amount','Illustrative allowance'],[s.gross,v],[['Category',s.type,'Scope drives method'],['Treatment',x[0],x[1]]],x[1]+'. '+(s.type==='poci'?'The zero bar is not a claim that lifetime expected losses are zero; initial expected losses enter the credit-adjusted yield.':'Actual measurement requires the appropriate cash-flow model and assumptions.'));}});
 add({id:'ecl',name:'12-month versus lifetime ECL',stage,title:'Twelve-month ECL is about default timing, not a year of cash shortfalls.',intro:'Project survival-weighted default losses and compare the first default-year contribution with the full remaining-life total.',chart:'Discounted loss by year of possible default (£m)',inputs:[a('ead','Starting exposure',0,300,10,100),a('pd','Annual conditional PD',0,25,.5,3,'%'),a('lgd','Conditional lifetime loss severity',0,100,5,40,'%'),a('years','Remaining life',1,10,1,5,'years'),a('eir','Original effective interest rate',0,15,.5,5,'%'),a('lag','Loss cash-shortfall delay after default',0,5,.5,2,'years'),sel('amort','Exposure profile',[['bullet','Bullet balance'],['amort','Straight-line annual runoff']],'bullet')],challenge:'Increase the loss delay beyond one year. Why does Stage 1 still include that loss if default is in year one?',formula:'ECL = Σ marginal PD(t) × conditional cash shortfall(t) / (1+EIR)^(t+delay)\n12-month ECL = contribution from default events in the first 12 months',simple:'Stage 1 restricts which possible default events are counted. Once such a default is counted, its resulting lifetime shortfalls belong in the estimate, including cash consequences beyond the next year.',scope:'Fixed-rate non-POCI performing debt under the general model. Annual conditional PD, deterministic exposure and loss severity. Entire conditional shortfall is placed at default-year end plus selected delay; LGD here is undiscounted shortfall severity, avoiding double discounting. No cure, fees or competing prepayment. IFRS 9 requires probability-weighted reasonable and supportable information; scenario uncertainty is isolated in the next lesson.',sources,compute(s){const r=M.ecl({ead:s.ead,pd:s.pd/100,lgd:s.lgd/100,years:s.years,eir:s.eir/100,lag:s.lag,amort:s.amort==='amort'?1:0});return {stats:[['12-month ECL',m(r.one)],['Lifetime ECL',m(r.life)],['Remaining-life PD',p(r.cumulative)]],bars:bars(r.rows.map(x=>'Default year '+x.t),r.rows.map(x=>x.loss)),headers:['Default year','Survival at start','Marginal PD','EAD','Shortfall cash year','PV loss'],rows:r.rows.map(x=>[x.t,p(x.survival),p(x.marginal),m(x.ead),x.t+s.lag,m(x.loss)]),explanation:`Default events in year one contribute ${m(r.one)}, including shortfalls paid at year ${1+s.lag}. All default years together contribute ${m(r.life)}.`};}});
 add({id:'sicr',name:'SICR and staging decisions',stage,title:'A significant increase is relative to the borrower’s starting risk.',intro:'Combine comparable lifetime default-risk estimates with qualitative deterioration and past-due backstops.',chart:'Comparable lifetime PD at origination and reporting (%)',inputs:[a('origin','Origination benchmark PD over comparable remaining horizon',.5,30,.5,2,'%'),a('current','Current PD over the same horizon',.5,60,.5,6,'%'),a('ratio','Illustrative relative increase threshold',1.5,5,.5,2,'×'),a('absolute','Illustrative absolute increase threshold',.5,10,.5,2,'percentage points'),a('dpd','Days past due',0,120,1,0,'days'),yes('watch','Qualitative SICR evidence'),yes('impaired','Credit-impaired evidence'),yes('rebut','Documented, supportable rebuttal of >30-day SICR presumption')],challenge:'Give two borrowers the same current PD but different origination benchmarks. Must their stages match?',formula:'Teaching quantitative trigger: PD ratio ≥ selected ratio AND PD increase ≥ selected absolute threshold\nQualitative SICR OR unrebutted >30 days past due → Stage 2\nCredit-impaired evidence / selected default backstop → Stage 3',simple:'SICR asks whether default risk has increased significantly since origination, not whether expected loss has become large. Strong collateral can reduce loss severity without removing credit deterioration.',scope:'Thresholds are user-defined teaching policy, not IFRS 9 prescribed cutoffs. PDs compare the same remaining horizon; an original full-life PD is not blindly compared with a shorter remaining-life PD. >30 DPD SICR presumption is rebuttable with supportable evidence. IFRS 9 default has a rebuttable presumption of no later than 90 DPD; this simulator does not implement a 90-day rebuttal and routes that case to Stage 3 under its stated policy. Credit impairment can occur earlier. Low-credit-risk expedient and cure require separate judgement; not implemented as automatic overrides.',sources,compute(s){const r=M.stage(s);return out([['Teaching stage','Stage '+r.stage],['Relative PD change',r.ratio.toFixed(2)+'×'],['ECL horizon',r.stage===1?'12-month':'Lifetime']],['Origination benchmark','Current comparable PD'],[s.origin,s.current],r.reasons.map(x=>['Decision evidence',x,'Not a universal threshold']),`Stage ${r.stage}: ${r.reasons.join('; ')}. Reassess using forward-looking information and documented policy, not delinquency alone.`);}});
 add({id:'scenarios',name:'Forward-looking scenarios',stage,title:'Average the scenario losses, not just the inputs.',intro:'Weight base, upside and downside economic states, each with its own PD and loss severity.',chart:'Lifetime ECL by scenario and weighted total (£m)',inputs:[a('pd','Base annual PD',.5,15,.5,3,'%'),a('lgd','Base LGD',10,70,5,40,'%'),a('stress','Downside PD multiplier',1,4,.25,2,'×'),a('downLGD','Downside LGD increase',0,30,5,15,'percentage points'),a('base','Base relative weight',0,100,5,60,'weight'),a('up','Upside relative weight',0,100,5,20,'weight'),a('down','Downside relative weight',0,100,5,20,'weight')],challenge:'Move probability toward the downside. Why can ECL rise even when it is not the most likely scenario?',formula:'ECL = Σ normalised scenario weight × scenario-specific discounted lifetime loss',simple:'Expected loss reflects a range of possible outcomes. A less likely state can matter substantially when its loss is large, and PD and recovery can deteriorate together in that state.',scope:'£100m bullet balance, five years, 5% EIR, no post-default lag. Upside PD=0.7×base, LGD=base−5pp (floored at zero); downside assumptions selected. Relative weights are normalised; all-zero selection is invalid and uses equal weights solely to keep the demonstration visible. Not a recommended number of scenarios or weighting method. Scenario-at-average-input comparison is a teaching contrast.',sources:[refs.ifrs,refs.scenario,refs.ecl],compute(s){const total=s.base+s.up+s.down,w=total?[s.base/total,s.up/total,s.down/total]:[1/3,1/3,1/3],pd=[s.pd/100,.7*s.pd/100,clamp(s.pd*s.stress/100)],lgd=[s.lgd/100,clamp((s.lgd-5)/100),clamp((s.lgd+s.downLGD)/100)],loss=pd.map((v,i)=>M.ecl({pd:v,lgd:lgd[i]}).life),weighted=sum(loss.map((v,i)=>v*w[i])),average=M.ecl({pd:sum(pd.map((v,i)=>v*w[i])),lgd:sum(lgd.map((v,i)=>v*w[i]))}).life;return out([['Weighted lifetime ECL',m(weighted)],['ECL at averaged inputs',m(average)],['Weight status',total?'Normalised to 100%':'INVALID · equal fallback']],['Base','Upside','Downside','Weighted ECL'],[...loss,weighted],loss.map((v,i)=>[['Base','Upside','Downside'][i],m(v),p(w[i])+' weight; PD '+p(pd[i])+'; LGD '+p(lgd[i])]),(total?'':'All weights are zero: choose at least one positive weight. Equal fallback displayed only for illustration. ')+`Scenario-weighted ECL is ${m(weighted)}. Using averaged PD and LGD instead gives ${m(average)} because loss measurement is nonlinear.`);}});
 add({id:'stage3',name:'Credit-impaired assets and interest',stage,title:'Credit impairment changes the recovery question and interest basis.',intro:'Value expected recovery cash for an already impaired loan and compare gross versus net interest bases.',chart:'Gross balance, recovery PV and allowance (£m)',inputs:[a('gross','Gross carrying amount',10,200,10,100),a('recovery','Expected recovery fraction',0,100,5,60,'%'),a('years','Recovery delay',0,6,.5,2,'years'),a('eir','Original EIR',0,15,.5,5,'%')],challenge:'If the borrower is already credit-impaired, why is multiplying by a fresh performing-loan PD inappropriate here?',formula:'Net carrying amount = PV(expected recoveries)\nAllowance = gross carrying amount − net carrying amount\nIllustrative interest revenue = original EIR × net carrying amount',simple:'For a credit-impaired asset, the central issue is how much and when cash can be recovered. Interest under the general model is calculated on the net basis in subsequent reporting periods when the asset is credit-impaired.',scope:'Non-POCI fixed-rate asset, one expected net recovery payment, no separately modelled costs, guarantee or contractual coupon stream. Gross carrying amount assumed consistent with original EIR. Recovery is already probability-weighted. Simplified interest snapshot; accrual timing, changes during a period and cure accounting require the actual standard.',sources,compute(s){const recovery=s.gross*s.recovery/100/(1+s.eir/100)**s.years,allowance=s.gross-recovery;return out([['Allowance',m(allowance)],['Net carrying amount',m(recovery)],['Net-basis annual interest',m(recovery*s.eir/100)]],['Gross balance','Net recovery PV','Allowance'],[s.gross,recovery,allowance],[['Gross-basis interest comparison',m(s.gross*s.eir/100),'For contrast, not the Stage 3 result'],['Net-basis interest',m(recovery*s.eir/100),'Original EIR × net amount']],`The recovery PV is ${m(recovery)}. The allowance is ${m(allowance)}, and the selected net-basis interest is ${m(recovery*s.eir/100)}.`);}});
 add({id:'revolving',name:'Revolving facilities and behavioural life',stage,title:'A cancellable line may expose the bank beyond its notice period.',intro:'Combine expected further drawings with an assumed behavioural exposure horizon.',chart:'Lifetime loss as behavioural horizon changes (£m)',inputs:[a('drawn','Drawn balance',0,200,5,60),a('undrawn','Undrawn commitment',0,200,5,40),a('ccf','Expected further utilisation',0,100,5,60,'%'),a('years','Behavioural exposure horizon',1,8,1,4,'years'),a('pd','Annual conditional PD',.5,20,.5,5,'%')],challenge:'Why might the contractual right to cancel tomorrow fail to limit ECL to one day?',formula:'EAD=drawn+CCF×undrawn\nECL horizon reflects qualifying revolving exposure and effective risk-management actions',simple:'A right that is not exercised in ordinary risk management may provide less protection than its legal wording suggests. Some revolving facilities expose a bank until risk is detected and managed in practice.',scope:'IFRS 9 5.5.20 / B5.5.39–40 qualifying revolving-facility concept. Not every commitment qualifies for the exception to the contractual horizon. Synthetic constant EAD, 70% LGD, 5% EIR. Behavioural life, expected draw and effective mitigation need evidence; no cancellation or repayment process is simulated.',sources:[refs.ifrs,refs.scenario],compute(s){const ead=s.drawn+s.undrawn*s.ccf/100,f=y=>M.ecl({ead,pd:s.pd/100,lgd:.7,years:y}).life,v=f(s.years);return {stats:[['EAD proxy',m(ead)],['Selected lifetime ECL',m(v)],['Selected life',s.years+' years']],series:[line('Lifetime ECL',Array.from({length:8},(_,i)=>[i+1,f(i+1)]))],xlabel:'Behavioural horizon (years)',headers:['Quantity','Value','Interpretation'],rows:[['Expected further drawing',m(ead-s.drawn),'Before risk mitigation takes effect'],['Lifetime ECL',m(v),'Not a contractual-notice shortcut']],explanation:`A ${s.years}-year behavioural horizon produces ${m(v)} of ECL in this selected model. The horizon must be supported by actual exposure and risk-management behaviour.`};}});
 add({id:'matrix',name:'Trade receivables and provision matrices',stage,title:'Ageing buckets can organise lifetime loss estimates.',intro:'Build a trade-receivables allowance from synthetic historical lifetime loss rates and a forward-looking adjustment.',chart:'Lifetime ECL by ageing bucket (£m)',inputs:[a('current','Current receivables',0,200,5,100),a('b30','1–30 days past due',0,100,5,30),a('b60','31–60 days past due',0,100,5,15),a('b90','61–90 days past due',0,100,5,10),a('old','Over 90 days past due',0,100,5,5),a('adjust','Forward-looking loss-rate multiplier',.5,2,.1,1.2,'×')],challenge:'If the customer mix changes, should you reuse the same historical matrix without adjustment?',formula:'Lifetime ECL = Σ ageing-bucket balance × forward-looking lifetime loss rate',simple:'A provision matrix groups receivables with shared loss patterns. Age is useful, but customers with different industries, locations or protections may need separate matrices.',scope:'Trade receivables without a significant financing component, mandatory simplified lifetime approach. Base synthetic rates 0.5%, 2%, 8%, 25%, 70%, scaled and capped at 100%. Assumes discounting immaterial for short-dated balances. These are lifetime loss rates, not annual PDs. Historical calibration, segmentation and forward-looking adjustments require evidence.',sources:[refs.ifrs,refs.matrix],compute(s){const names=['Current','1–30 DPD','31–60 DPD','61–90 DPD','>90 DPD'],b=[s.current,s.b30,s.b60,s.b90,s.old],rates=[.005,.02,.08,.25,.7].map(x=>clamp(x*s.adjust)),loss=b.map((x,i)=>x*rates[i]),total=sum(b);return {stats:[['Receivables',m(total)],['Lifetime ECL',m(sum(loss))],['Coverage',total?p(sum(loss)/total):'N/A · no balance']],bars:bars(names,loss),headers:['Ageing bucket','Balance','Adjusted loss rate','ECL'],rows:b.map((x,i)=>[names[i],m(x),p(rates[i]),m(loss[i])]),explanation:`The matrix produces ${m(sum(loss))} of lifetime ECL. It does not use the general-model Stage 1 / Stage 2 SICR switch.`};}});
 add({id:'poci',name:'POCI assets',stage,title:'Initial expected losses are embedded in the credit-adjusted yield.',intro:'Compare initial expected recovery with revised recovery at the same measurement date to isolate a POCI loss change.',chart:'Initial and revised expected recovery present values (£m)',inputs:[a('initial','Initially expected recovery cash',10,150,5,60),a('revised','Revised expected recovery cash',0,150,5,50),a('years','Remaining cash-flow horizon',1,8,1,3,'years'),a('rate','Credit-adjusted EIR',0,20,.5,8,'%')],challenge:'If recovery expectations improve, can the change in lifetime ECL be favourable?',formula:'Illustrative cumulative ECL change = PV(initial expected recovery) − PV(revised recovery)\nDiscount at the credit-adjusted EIR',simple:'A POCI asset starts with credit impairment already reflected in its expected cash flows and yield. Later accounting focuses on changes from that initial expectation, including favourable changes.',scope:'Same-date comparison to isolate changed recovery expectations; not a full amortised-cost roll-forward over elapsed time. Initial fair value assumed equal to PV of initial expected cash at selected credit-adjusted EIR. Negative displayed change means a favourable impairment change. No general-model staging or separate initial allowance is imposed.',sources:[refs.ifrs,refs.poci],compute(s){const d=(1+s.rate/100)**s.years,b=s.initial/d,r=s.revised/d,change=b-r;return out([['Initial recovery PV',m(b)],['Revised recovery PV',m(r)],['Cumulative loss change',m(change)]],['Initial expectation PV','Revised expectation PV','Loss change'],[b,r,change],[['Initial ECL','Included in expected cash flows','Embedded in credit-adjusted yield'],['Subsequent change',m(change),change<0?'Favourable change':'Adverse change']],`The revision creates a ${change<0?'favourable':'adverse'} loss change of ${m(Math.abs(change))}. Do not apply ordinary Stage 1 provisioning to the initial POCI loss estimate.`);}});
 add({id:'modifications',name:'Forbearance, modification and cure',stage,title:'Changing the contract does not automatically cure the borrower.',intro:'Revalue modified contractual cash flows at the original EIR where modification does not cause derecognition.',chart:'Original carrying amount and modified cash-flow PV (£m)',inputs:[a('coupon','Modified annual coupon',0,10,.5,3,'%'),a('principal','Principal repayment at maturity',50,100,5,100),a('years','New remaining term',1,10,1,5,'years'),a('eir','Original EIR',1,10,.5,5,'%'),yes('distress','Continuing borrower financial distress','yes')],challenge:'If payments become affordable after a concession, does the loan immediately return to Stage 1?',formula:'Modification result = PV(modified contractual cash flows at original EIR) − pre-modification gross carrying amount',simple:'A concession can reduce the lender’s contractual claim and help the borrower repay. It does not erase the borrower’s credit history or the need to assess continuing deterioration.',scope:'Non-derecognised fixed-rate loan, original gross carrying amount £100m, annual modified coupon on £100m and selected final principal. No fees or ECL recalculation in this valuation trace. Derecognition assessment is separate; if it occurs, new recognition and possible POCI treatment require review. Cure and probation policies need evidence, not an automatic switch.',sources,compute(s){const pv=sum(Array.from({length:s.years},(_,i)=>(s.coupon+(i===s.years-1?s.principal:0))/(1+s.eir/100)**(i+1))),delta=pv-100;return out([['Modified contractual PV',m(pv)],['Modification gain / loss',m(delta)],['Credit review',s.distress==='yes'?'Distress persists':'Assess improvement evidence']],['Before modification','Modified PV','Gain / loss'],[100,pv,delta],[['Derecognition','Assumed no','Requires separate assessment'],['SICR / impairment','Reassess','Concession is not automatic cure']],`The contractual modification changes gross value by ${m(delta)}. The credit-loss allowance and staging assessment remain separate work.`);}});
 add({id:'allowance',name:'Allowance movements and write-offs',stage,title:'An allowance movement needs a clear explanation.',intro:'Reconcile opening and closing allowances through new exposures, remeasurement, releases and write-offs.',chart:'Allowance bridge components (£m)',inputs:[a('opening','Opening allowance',0,30,.5,10),a('new','New lending ECL',0,15,.5,2),a('remeasure','Adverse remeasurement / stage effects',0,20,.5,4),a('release','Requested allowance release',0,20,.5,1),a('writeoff','Requested write-off against allowance',0,20,.5,3)],challenge:'Why can an allowance fall even when credit performance has worsened?',formula:'Closing allowance = opening + additions + remeasurement − releases − write-offs',simple:'A write-off can use an existing allowance and reduce its closing balance. That decline is not evidence of better credit quality. Movement analysis distinguishes risk changes from balance removals.',scope:'Allowance-only bridge, no FX, acquisitions, transfers or gross carrying amount roll-forward. Releases capped at available allowance, then write-offs capped at the remainder to avoid negative stock. This cap is a teaching constraint, not a rule preventing real write-offs above allowance; such cases require additional expense. Write-off applies when no reasonable expectation of recovery remains, and enforcement can continue.',sources,compute(s){const available=s.opening+s.new+s.remeasure,release=Math.min(s.release,available),writeoff=Math.min(s.writeoff,available-release),close=available-release-writeoff;return out([['Closing allowance',m(close)],['Applied release',m(release)],['Applied write-off',m(writeoff)]],['Opening','New lending','Remeasurement','Release','Write-off','Closing'],[s.opening,s.new,s.remeasure,-release,-writeoff,close],[['Requested release',m(s.release),'Capped to available stock here'],['Requested write-off',m(s.writeoff),'Capped to remaining stock here'],['Reconciliation',m(close),'Opening plus signed movements']],`The closing allowance is ${m(close)}. Write-offs consume ${m(writeoff)} of existing allowance; they should not be interpreted as credit improvement.`);}});
 add({id:'overlays',name:'Overlays and model limitations',stage:'05 · Stress and model uncertainty',title:'Address a missing risk without counting it twice.',intro:'Separate a gross scenario effect from the portion already captured by the model and a residual management adjustment.',chart:'Model ECL and residual adjustment (£m)',inputs:[a('model','Model ECL',0,30,.5,10),a('risk','Gross estimated missing-risk effect',0,15,.5,4),a('captured','Share already captured in model',0,100,5,50,'%'),a('confidence','Evidence-supported proportion of residual',0,100,5,75,'%')],challenge:'If a model enhancement captures the previously missing effect, should the old overlay remain unchanged?',formula:'Illustrative residual adjustment = gross effect × (1 − already-captured share) × selected evidence proportion',simple:'An overlay should address a named limitation with evidence, ownership and a review plan. It can become double counting if the model is later updated but the adjustment is left in place.',scope:'Pure attribution illustration. The evidence proportion is a user-defined sensitivity, not an IFRS formula or permission to discount known risk. Actual adjustments must support an unbiased estimate and may be positive or negative. This example restricts inputs to adverse additions; no automatic conservative cushion or target allowance is prescribed.',sources:[refs.ecl,refs.model,refs.ifrs],compute(s){const residual=s.risk*(1-s.captured/100),overlay=residual*s.confidence/100;return out([['Residual effect',m(residual)],['Selected adjustment',m(overlay)],['Adjusted ECL',m(s.model+overlay)]],['Model ECL','Adjustment','Total'],[s.model,overlay,s.model+overlay],[['Already captured',m(s.risk-residual),'Remove duplication'],['Residual sensitivity',m(residual),'Needs evidence and governance'],['Review','Owner, expiry and model remediation','Track changes over time']],`The selected adjustment is ${m(overlay)} after considering overlap. A model update should trigger reassessment of whether the same risk remains outside the model.`);}});
 add({id:'stress',name:'Macro stress and linked PD / LGD',stage:'05 · Stress and model uncertainty',title:'A recession can affect default and recovery together.',intro:'Apply a macro severity factor to PD odds and recovery loss severity, then compare stressed and baseline lifetime losses.',chart:'Lifetime ECL across macro severity levels (£m)',inputs:[a('pd','Base annual PD',.5,15,.5,3,'%'),a('lgd','Base LGD',10,70,5,40,'%'),a('severity','Macro stress severity',0,3,.25,1,'index'),a('sensitivity','Log-odds response per severity unit',0,1.5,.1,.5,'coefficient'),a('recovery','LGD increase per severity unit',0,10,1,5,'percentage points')],challenge:'Why can stressing only PD understate losses in a collateral-backed portfolio?',formula:'Stressed PD = sigmoid(logit(base PD)+β×severity)\nStressed LGD = min(100%, base LGD + recovery sensitivity×severity)',simple:'Borrowers and collateral can respond to the same economic shock. A model that worsens PD while keeping recovery unusually favourable may miss this joint vulnerability.',scope:'£100m five-year bullet, 5% EIR, synthetic single-factor macro mapping and coefficients. No econometric estimation or macro forecast. Stress is a conditional adverse outcome, not automatically probability-weighted IFRS 9 ECL. Results do not calculate bank capital or prescribe scenario weights.',sources:[refs.ecl,refs.model,refs.scenario],compute(s){const value=z=>M.ecl({pd:M.sigmoid(M.logit(s.pd/100)+s.sensitivity*z),lgd:clamp((s.lgd+s.recovery*z)/100)}).life,base=value(0),stress=value(s.severity);return {stats:[['Baseline lifetime ECL',m(base)],['Stressed lifetime ECL',m(stress)],['Stressed annual PD',p(M.sigmoid(M.logit(s.pd/100)+s.sensitivity*s.severity))]],series:[line('Conditional ECL',Array.from({length:31},(_,i)=>[i/10,value(i/10)]))],xlabel:'Macro severity index',headers:['Driver','Baseline','Stressed'],rows:[['PD',s.pd+'%',p(M.sigmoid(M.logit(s.pd/100)+s.sensitivity*s.severity))],['LGD',s.lgd+'%',p(clamp((s.lgd+s.recovery*s.severity)/100))]],explanation:`Joint PD/LGD stress changes lifetime ECL from ${m(base)} to ${m(stress)}. Scenario weighting is needed before using conditional results in an expected-loss estimate.`};}});
 add({id:'governance',name:'Validation, governance and coverage map',stage:'06 · Decisions and governance',title:'A credit model needs evidence across its whole lifecycle.',intro:'Review the modelling workflow and see which evidence gaps remain before a model is ready for use.',chart:'Selected evidence readiness by lifecycle area',inputs:[yes('data','Data lineage and target review complete'),yes('fit','Development and calibration review complete'),yes('validation','Independent validation complete'),yes('fair','Responsible-use and proxy review complete'),yes('monitor','Monitoring, limits and escalation assigned'),yes('accounting','Accounting / regulatory policy reviewed')],challenge:'If all the boxes are checked, does that certify the model or the bank’s accounting?',formula:'Evidence checklist ≠ approval score\nIdentify → develop → validate → approve → use → monitor → change / retire',simple:'A technically accurate calculation can still fail through bad data, inappropriate use or weak governance. Named ownership and independent challenge connect the model to decisions and reporting.',scope:'Illustrative checklist, not an audit, legal assessment or regulatory certification. PRA SS1/23 has defined applicability; consult its current scope. This learning path covers core lending, portfolio, modelling and IFRS 9 concepts, with deliberately simplified models. Specialist sovereign, financial-institution, project, securitisation, regulatory IRB capital and legal-credit questions require deeper methods.',sources:[refs.model,refs.ifrs,refs.capital],compute(s){const names=['Data','Development','Validation','Responsible use','Monitoring','Policy'],ks=['data','fit','validation','fair','monitor','accounting'],v=ks.map(k=>s[k]==='yes'?1:0);return out([['Evidence areas selected',sum(v)+' / 6'],['Unreviewed areas',6-sum(v)+''],['Approval','Not determined']],names,v,[['Covered here','PD / LGD / EAD, portfolio loss, modelling, IFRS 9','Synthetic educational models'],['Related Quant$ense paths','SA-CCR, SA-CVA, XVA, IRRBB','Counterparty and valuation connections'],['Further depth','IRB formulae, securitisation, sovereign / FI models','Not implemented as complete calculators']],`${6-sum(v)} evidence areas remain unselected. Checking a box records a teaching choice; actual approval requires review of the evidence and intended use.`);}});
})();
